import json, urllib.request, ssl, re

ctx = ssl._create_unverified_context()
HDRS = {"Content-Type": "application/json", "Authorization": "Bearer $thehive_api_key"}

# input: {"case_number": 42} via execution argument (empty $exec_argument at start nodes)
raw = self.full_execution.get("execution_argument", "") if isinstance(self.full_execution, dict) else ""
case_number = None
try:
    arg = json.loads(raw) if raw else {}
    case_number = int(arg.get("case_number"))
except Exception:
    case_number = None

def fail(msg):
    print(json.dumps({"narrative_msg": msg.replace('"', "'"), "found": "false"}))

if case_number is None:
    fail("DRAFT NARRATIVE: no case_number supplied. Trigger with execution argument {'case_number': N}.")
else:
    case = None
    try:
        req = urllib.request.Request("$thehive_url/api/case/_search",
            data=json.dumps({"query": {"caseId": case_number}, "range": "0-1"}).encode(),
            headers=HDRS, method="POST")
        hits = json.loads(urllib.request.urlopen(req, context=ctx, timeout=15).read().decode())
        if isinstance(hits, list) and hits:
            case = hits[0]
    except Exception as e:
        case = None
    if not case:
        fail(f"DRAFT NARRATIVE: case #{case_number} not found in TheHive.")
    else:
        case_id = case.get("_id") or case.get("id", "")
        observables = []
        try:
            req = urllib.request.Request("$thehive_url/api/case/artifact/_search?range=0-30",
                data=json.dumps({"query": {"_parent": {"_type": "case", "_query": {"_id": case_id}}}}).encode(),
                headers=HDRS, method="POST")
            arts = json.loads(urllib.request.urlopen(req, context=ctx, timeout=15).read().decode())
            if isinstance(arts, list):
                for a in arts:
                    observables.append(f"{a.get('dataType','?')}={a.get('data','?')}" +
                        (" (ioc)" if a.get("ioc") else ""))
        except Exception:
            observables = []

        cf = case.get("customFields", {}) if isinstance(case.get("customFields", {}), dict) else {}
        def cf_val(k):
            v = cf.get(k, {})
            return v.get("string", "") if isinstance(v, dict) else ""

        sev_map = {1: "Low", 2: "Medium", 3: "High", 4: "Critical"}
        evidence = {
            "case_number": case_number,
            "title": str(case.get("title", ""))[:200],
            "severity": sev_map.get(case.get("severity", 1), "?"),
            "status": case.get("status", ""),
            "tags": case.get("tags", [])[:10],
            "description": str(case.get("description", ""))[:1500],
            "community_id": cf_val("community_id"),
            "zeek_uid": cf_val("zeek_uid"),
            "observables": observables[:20]
        }

        system = ("You are a SOC analyst drafting an incident ticket narrative for a small "
            "home lab SOC. Use ONLY the evidence provided - never invent IPs, hostnames, "
            "times, or indicators. Copy any MITRE technique ID character-for-character from the evidence, and only cite IDs that appear there - if unsure, omit the ID. Plain text, no markdown headers. Structure: one summary "
            "sentence; what the evidence shows; observables involved; impact assessment; "
            "recommended next steps. 150-220 words. Where evidence is missing, say so "
            "rather than filling the gap.")
        prompt = ("/no_think Draft the incident narrative from this case evidence. "
            "Return plain text only. Evidence: " + json.dumps(evidence))
        payload = json.dumps({"model": "qwen3:8b", "prompt": prompt, "system": system,
            "stream": False, "keep_alive": "24h",
            "options": {"temperature": 0.3}}).encode()
        text = ""
        for _attempt in range(2):
            try:
                req = urllib.request.Request("$ollama_url/api/generate", data=payload,
                    headers={"Content-Type": "application/json"}, method="POST")
                text = json.loads(urllib.request.urlopen(req, timeout=120).read().decode()).get("response", "")
                text = re.sub(r"<think>.*?</think>", "", text, flags=re.DOTALL).strip()
                if text:
                    break
            except Exception:
                text = ""
        if not text:
            fail(f"DRAFT NARRATIVE: LLM unavailable for case #{case_number}. Case data was retrieved OK.")
        else:
            text = text.replace('"', "'").replace("\\", "")
            text = text.replace("\r", "").replace("\n", "\\n")
            header = (f"**DRAFT INCIDENT NARRATIVE - case #{case_number}: {evidence['title'][:80]}**\\n"
                "_AI draft from logged evidence. EDIT AND APPROVE before it goes in the ticket._\\n\\n")
            msg = header + text
            if len(msg) > 1900:
                msg = msg[:1897] + "..."
            print(json.dumps({"narrative_msg": msg, "found": "true", "case_id": case_id,
                "observable_count": len(observables)}))
